function divideKb(float $a, float $b): float {
    if ($b === 0.0) {
        throw new InvalidArgumentException("Divisor must not be zero.");
    }
    return $a / $b;
}
echo divideKb(10, 2);
try {
    divideKb(10, 0);
} catch (InvalidArgumentException $e) {
    echo $e->getMessage();
}

class KbPaymentFailed extends Exception {}
function chargeKb(float $amount): void {
    if ($amount <= 0) {
        throw new KbPaymentFailed("Amount must be positive.");
    }
}
try {
    chargeKb(0);
} catch (KbPaymentFailed $e) {
    echo "Payment problem: " . $e->getMessage();
} finally {
    echo " Done.";
